/* @lc app=leetcode id=1905 lang=kotlin */ class Solution { fun countSubIslands(grid1: Array<IntArray>, grid2: Array<IntArray>): Int = IntArray(1).let { ans -> intArrayOf(0, 1, 0, -1, 0).let { d -> (0 until grid2.size).forEach { r -> (0 until grid2[0].size).forEach { c -> if (grid2[r][c] == 1) grid2[r][c] = 0.also { java.util.ArrayDeque<IntArray>().also { q -> q.add(intArrayOf(r, c)) }.let { q -> IntArray(1) { 1 }.also { isSub -> while (!q.isEmpty()) q.poll().also { p -> if (grid1[p[0]][p[1]] == 0) isSub[0] = 0 }.also { p -> (0 until 4).forEach { k -> (p[0] + d[k] to p[1] + d[k + 1]).let { (nr, nc) -> if (nr in grid2.indices && nc in grid2[0].indices && grid2[nr][nc] == 1) grid2[nr][nc] = 0.also { q.add(intArrayOf(nr, nc)) } } } } }.also { isSub -> if (isSub[0] == 1) ans[0]++ } } } } }.run { ans[0] } } } }